import{_ as n,C as t,o as r,c as i,E as o,a2 as d}from"./chunks/framework.IIAdu7fg.js";const c="/joinwell52/assets/task-identity-20261029/same-id.figure.en.svg",k=JSON.parse('{"title":"Same task ID. Is it still the same work?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Same task ID. Is it still the same work?","date":"2026-10-29","published_date":"2026-10-29","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Same task ID. Is it still the same work?","summary":"An old test supports a new report; a new task receives a previously archived ID. Two FCoP and CodeFlowMu experiments ask what actually binds identity to evidence.","cover":"/assets/task-identity-20261029/same-id.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Pinned public source; controlled FCoP v3 compatibility and CodeFlowMu-open project probes","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-10-29-same-task-id-different-work.md","filePath":"en/research/2026-10-29-same-task-id-different-work.md","lastUpdated":1793256911000}'),h={name:"en/research/2026-10-29-same-task-id-different-work.md"};function l(p,e,u,m,b,w){const a=t("ArticleCover"),s=t("ArticleTableScroll");return r(),i("div",null,[o(a,{image:"/assets/task-identity-20261029/same-id.cover-v1.png",kicker:"Open-source engineering · Local comparison",title:"Same task ID. Is it still the same work?",summary:"An old test supports a new report; a new task receives a previously archived ID. Two FCoP and CodeFlowMu experiments ask what actually binds identity to evidence.",version:"2026-10-29",languageHref:"/zh/research/2026-10-29-same-task-id-different-work",languageLabel:"中文"}),o(s,{language:"en"}),e[0]||(e[0]=d('<h1 id="same-task-id-is-it-still-the-same-work" tabindex="-1">Same task ID. Is it still the same work? <a class="header-anchor" href="#same-task-id-is-it-still-the-same-work" aria-label="Permalink to &quot;Same task ID. Is it still the same work?&quot;">​</a></h1><p>An AI team receives a job numbered <code>001</code>. When an executor submits a report, the reviewer uses that number to find the test result, deliverable, and history. Matching numbers appear to connect the evidence.</p><p>We tried two controlled comparisons in temporary projects. In one, <strong>a new session&#39;s completion report was supported by a test from an older session</strong>. In the other, <strong>a new task received the ID of a task already moved into deep history</strong>. Neither is a known production incident. Together they make a precise question unavoidable: a number helps us find records, but does it prove that those records belong to <strong>this instance of work</strong>?</p><h2 id="two-outside-projects-prompted-a-check-of-our-own" tabindex="-1">Two outside projects prompted a check of our own <a class="header-anchor" href="#two-outside-projects-prompted-a-check-of-our-own" aria-label="Permalink to &quot;Two outside projects prompted a check of our own&quot;">​</a></h2><p><a href="https://github.com/B0yko/agent-claimcheck" target="_blank" rel="noreferrer">agent-claimcheck</a> is an open-source tool for checking an agent&#39;s success claims against tool receipts and environment state probes. Claims it cannot verify are left for human review. It reminds us that <strong>“done” is a claim that needs evidence</strong>. <a href="https://github.com/gastownhall/beads" target="_blank" rel="noreferrer">Beads</a> is a persistent task and dependency tracker for coding agents. Its <a href="https://github.com/gastownhall/beads/pull/7931" target="_blank" rel="noreferrer">PR #7931</a> retains old identities on a specific cleanup path so a late operation cannot treat a retired ID as fresh.</p><p>These projects do not study the same implementation. One illuminates evidence for a claim; the other illuminates identity after cleanup. Their intersection matters to us because we use two adjacent systems: <strong>FCoP</strong> records an AI team&#39;s tasks and reports as files; <strong>CodeFlowMu</strong> coordinates execution, collects action evidence, and handles review. What does a task ID promise when it crosses that boundary?</p><p>The experiments below pin the public source available on October 29, 2026: FCoP 4.0.5&#39;s <strong>v3 compatibility API</strong> and the public <code>main</code> branch of CodeFlowMu-open. CodeFlowMu-open is a frozen historical public edition; it does not represent the current private product. We do not present either outside project&#39;s tests as our own results.</p><h2 id="boundary-one-the-task-stayed-the-same-but-the-execution-did-not" tabindex="-1">Boundary one: the task stayed the same, but the execution did not <a class="header-anchor" href="#boundary-one-the-task-stayed-the-same-but-the-execution-did-not" aria-label="Permalink to &quot;Boundary one: the task stayed the same, but the execution did not&quot;">​</a></h2><p>First, we used FCoP&#39;s compatibility API to create a real task and completion report. The report cites the task and says <code>status: done</code>, but it has <strong>no session or run identifier</strong>. That is the file the API currently emits.</p><p>We then supplied CodeFlowMu with a controlled action history. An older session ran <code>npm test</code> at 10:00 with exit code 0. A new session wrote a report at 11:00 claiming that this delivery passed its test. The new session did not run a test. We passed the FCoP-generated report through CodeFlowMu&#39;s report-processing entry point.</p><table tabindex="0"><thead><tr><th>Report input</th><th>Fact-check result</th><th>Subsequent handling</th></tr></thead><tbody><tr><td>Original FCoP report: task ID, no session binding</td><td><code>pass</code></td><td>Proceeds toward review</td></tr><tr><td>Same report explicitly bound to the new session</td><td><code>needs_admin</code></td><td>Held for human reconciliation</td></tr></tbody></table><p>The old test is not necessarily invalid. A team may reasonably reuse it if the code, environment, and acceptance conditions still apply and someone explicitly accepts that inheritance. The experiment shows a narrower boundary: <strong>without a session binding, the tested path aggregates action evidence by task ID; the report itself cannot distinguish legitimate inheritance from a coincidental match to older work.</strong> Once the new session is bound explicitly, its missing test becomes a visible uncertainty.</p><p>CodeFlowMu also has two distinct checks here. <code>review_check</code> can check whether a report refers to the right task, but it does not read the contents of a deliverable named in the report. Fact checking occurs later in the report-processing path. We exercised that cross-project path for the table above; a single check function&#39;s <code>ok</code> does not mean the business outcome was approved.</p><p><img src="'+c+'" alt="The task ID matches, but inheritance between the old session&#39;s action and the new report is unspecified"></p><p><em>Figure: evidence association in the first controlled experiment. “Unresolved” names an engineering question, not a finding that a real delivery was wrongly approved.</em></p><h2 id="boundary-two-the-work-changed-but-the-number-did-not" tabindex="-1">Boundary two: the work changed, but the number did not <a class="header-anchor" href="#boundary-two-the-work-changed-but-the-number-did-not" aria-label="Permalink to &quot;Boundary two: the work changed, but the number did not&quot;">​</a></h2><p>Next we tested the identity of the task itself. FCoP&#39;s v3 compatibility API can move a closed task into date-sharded deep history. In a temporary project with one task created that day, we made <code>TASK-20261029-001</code>, archived it, moved it into history, and created a different task on the same day.</p><p>The new task received <code>TASK-20261029-001</code> again. The old file still existed. A normal task lookup by that ID returned the <strong>new task</strong>, while a history lookup returned the <strong>old task</strong>. A late report containing only that ID cannot identify which generation of work it intended to answer. We wrote such a report, but <strong>we did not observe a real external side effect from a late retry</strong>.</p><p>This result has a strict scope. It concerns the <strong>v3 compatibility API</strong> retained in FCoP 4.0.5. FCoP 4.0&#39;s native Core uses UUID task identities, so the compatibility result cannot be attributed to its native mechanism. CodeFlowMu-open&#39;s own task ID allocator scans history: with <code>001</code> in history, our comparison returned <code>002</code>. We therefore cannot claim that all CodeFlowMu task-creation paths reuse IDs.</p><h2 id="one-question-behind-both-observations" tabindex="-1">One question behind both observations <a class="header-anchor" href="#one-question-behind-both-observations" aria-label="Permalink to &quot;One question behind both observations&quot;">​</a></h2><p>In the first experiment, the <strong>logical task stayed the same but the execution session changed</strong>. In the second, the <strong>logical task changed while the visible ID was reused</strong>. These are different mechanisms. They present the reviewer with the same question: when two records share a <code>task_id</code>, what else establishes that the evidence proves the work now under review?</p><p>Three practical checks follow:</p><ol><li><strong>Which job is this?</strong> After archival or migration, is the old identity still reserved, or is there a different job with the same label?</li><li><strong>Which execution produced it?</strong> Which session or run produced the report and the supporting action?</li><li><strong>How was earlier evidence inherited?</strong> If it may be reused, who accepted its scope, and what changes would invalidate it?</li></ol><p>These checks are <strong>research questions raised by the experiments</strong>, not a protocol we have implemented. A possible design may need a stable task identity, an execution instance, and an explicit evidence-inheritance record. Before choosing a format, we need to examine FCoP compatibility writes, every relevant CodeFlowMu creation path, and the distribution of reports in real projects.</p><p>If your agents handle real work, one check is available now: when the system says “tests passed, task complete,” ask <strong>which execution produced the test for this delivery</strong>. If the answer is only the same task number, the evidence chain is not yet fully explained. For engineers, the harder follow-up is when an older test may legitimately be inherited—and how little identity data must survive long-term archival to prevent mistaken reuse without retaining content forever.</p><p>Pinned revisions, reproduction scripts, observed results, and limits are in the <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-10-29-task-identity/00-report.en.md" target="_blank" rel="noreferrer">English experiment report</a>. These are controlled temporary-project comparisons. We have not measured incidence in real projects or observed an online misapproval or duplicate execution. <a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',26))])}const y=n(h,[["render",l]]);export{k as __pageData,y as default};
